/**
 * Shim `window.fetch` untuk mode native (bundel lokal).
 *
 * Saat app berjalan native dengan SPA di-bundel lokal (origin https://localhost),
 * semua request path-relatif (`/api/...`, `/files/...`) harus diarahkan ke host
 * backend produksi, dan setiap request diberi header Authorization token.
 *
 * Efeknya: seluruh pemanggil (frappe-ui `createResource`, `frappeRequest`, dan
 * ~150 pemanggilan `fetch('/api/...')` langsung di komponen) otomatis benar
 * tanpa perlu diubah satu per satu.
 *
 * Di browser biasa (bukan native) shim TIDAK dipasang → perilaku same-origin
 * dengan cookie tetap seperti semula.
 *
 * WAJIB di-import sangat awal di main.js (setelah polyfills, sebelum modul yang
 * bisa memicu request).
 */
import { isNativeApp, API_BASE, getToken } from './mobile'

if (isNativeApp() && typeof window !== 'undefined' && window.fetch) {
	// index.html bundel lokal tidak dirender Jinja → window.csrf_token berisi
	// literal "{{ csrf_token }}". Token auth tidak butuh CSRF, jadi kosongkan
	// agar tidak terkirim sebagai header CSRF yang tidak valid.
	try {
		if (!window.csrf_token || String(window.csrf_token).includes('{{')) {
			window.csrf_token = ''
		}
	} catch (e) {
		/* abaikan */
	}

	const origFetch = window.fetch.bind(window)

	window.fetch = function patchedFetch(input, init) {
		const opts = init ? Object.assign({}, init) : {}

		const isRequestObj =
			typeof Request !== 'undefined' && input instanceof Request
		let url = isRequestObj ? input.url : String(input)

		// Path-relatif ("/api/...", "/files/...") → absolut ke backend produksi.
		if (url && url.charAt(0) === '/') {
			url = API_BASE + url
		}

		// Gabungkan header lalu pasang Authorization token bila ada.
		const headers = new Headers(
			(isRequestObj ? input.headers : opts.headers) || {}
		)
		const token = getToken()
		if (token && !headers.has('Authorization')) {
			headers.set('Authorization', 'token ' + token)
		}
		opts.headers = headers

		// Token auth tidak butuh cookie. Omit credentials supaya CORS bisa pakai
		// wildcard origin (tanpa Access-Control-Allow-Credentials).
		opts.credentials = 'omit'

		if (isRequestObj) {
			// Bangun ulang Request dengan URL absolut, pertahankan method/body.
			return origFetch(new Request(url, input), opts)
		}
		return origFetch(url, opts)
	}
}
