<template>
	<!-- Overlay full-screen. Hanya dirender saat pdfState.open. -->
	<div
		v-if="pdfState.open"
		class="fixed inset-0 z-[60] flex flex-col bg-[#171717]"
		style="padding-top: env(safe-area-inset-top)"
	>
		<!-- Header: Back (kiri) · judul · zoom · Download (kanan) -->
		<div
			class="flex shrink-0 items-center gap-1.5 border-b border-white/10 bg-[#171717] px-3 py-2 text-white"
		>
			<button
				type="button"
				class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-white/90 active:bg-white/10"
				aria-label="Kembali"
				title="Kembali"
				@click="close"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-6 w-6"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="m12 19-7-7 7-7" />
					<path d="M19 12H5" />
				</svg>
			</button>
			<span class="min-w-0 flex-1 truncate text-sm font-medium">{{ pdfState.title }}</span>
			<button
				type="button"
				class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-white/90 active:bg-white/10 disabled:opacity-40"
				aria-label="Perkecil"
				:disabled="loading || scale <= MIN_SCALE"
				@click="zoom(-0.25)"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
				>
					<path d="M5 12h14" />
				</svg>
			</button>
			<button
				type="button"
				class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-white/90 active:bg-white/10 disabled:opacity-40"
				aria-label="Perbesar"
				:disabled="loading || scale >= MAX_SCALE"
				@click="zoom(0.25)"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
				>
					<path d="M12 5v14M5 12h14" />
				</svg>
			</button>
			<button
				type="button"
				class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-white/90 active:bg-white/10 disabled:opacity-40"
				aria-label="Download PDF"
				title="Download PDF"
				:disabled="downloading"
				@click="download"
			>
				<svg
					v-if="!downloading"
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
					<path d="M7 10l5 5 5-5" />
					<path d="M12 15V3" />
				</svg>
				<svg
					v-else
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5 animate-spin"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="M21 12a9 9 0 1 1-6.219-8.56" />
				</svg>
			</button>
		</div>

		<!-- Body: daftar canvas per halaman, scrollable -->
		<div
			ref="scroller"
			class="min-h-0 flex-1 overflow-auto bg-[#262626]"
			style="padding-bottom: env(safe-area-inset-bottom)"
		>
			<div v-if="loading" class="flex h-full items-center justify-center text-white/70">
				<svg
					class="h-6 w-6 animate-spin"
					viewBox="0 0 24 24"
					fill="none"
					xmlns="http://www.w3.org/2000/svg"
				>
					<circle
						cx="12"
						cy="12"
						r="10"
						stroke="currentColor"
						stroke-width="3"
						opacity="0.25"
					/>
					<path
						d="M22 12a10 10 0 0 0-10-10"
						stroke="currentColor"
						stroke-width="3"
						stroke-linecap="round"
					/>
				</svg>
				<span class="ml-2 text-sm">Memuat PDF…</span>
			</div>

			<p
				v-else-if="error"
				class="px-6 py-10 text-center text-sm text-red-300 whitespace-pre-wrap"
			>
				{{ error }}
			</p>

			<div v-else class="flex flex-col items-center gap-3 py-3">
				<canvas
					v-for="p in pageCount"
					:key="p"
					:ref="(el) => (canvasRefs[p - 1] = el)"
					class="max-w-full bg-white shadow-lg"
				/>
			</div>
		</div>

		<!-- Toast unduhan (sukses / gagal) -->
		<div
			v-if="toast"
			class="pointer-events-none absolute inset-x-0 bottom-0 flex justify-center px-4"
			style="padding-bottom: calc(env(safe-area-inset-bottom) + 16px)"
		>
			<div
				class="max-w-full rounded-xl bg-black/85 px-4 py-2.5 text-center text-sm text-white shadow-lg ring-1 ring-white/10"
			>
				{{ toast }}
			</div>
		</div>
	</div>
</template>

<script setup>
import { nextTick, ref, watch } from 'vue'
// Build "legacy" (bukan build standar): sudah ditranspilasi + membawa polyfill
// core-js di DALAM bundle-nya, termasuk `Promise.withResolvers` (ES2024) yang
// dipakai pdfjs v4. Tanpa ini, mesin lama gagal dengan
// "Promise.withResolvers is not a function" — dan polyfill di thread utama TIDAK
// menolong karena worker punya lingkup global sendiri.
import * as pdfjsLib from 'pdfjs-dist/legacy/build/pdf.mjs'
// Worker di-bundle Vite jadi CLASSIC worker (.js), bukan di-fetch sebagai .mjs.
// Alasan (penting untuk APK Capacitor):
//   1. Android WebView lama tidak mendukung module worker → `new Worker(url,
//      {type:'module'})` milik pdfjs gagal.
//   2. Fallback pdfjs ("fake worker") meng-import() file .mjs; di Android, .mjs
//      disajikan dengan MIME salah (octet-stream) → ES module import ditolak →
//      "Failed to fetch dynamically imported module".
// `?worker` menghasilkan chunk .js + instansiasi lokal → tak ada fetch/import
// yang bisa gagal, dan tetap offline-friendly.
// Worker WAJIB dari folder legacy juga, agar polyfill ikut di lingkup worker.
import PdfWorker from 'pdfjs-dist/legacy/build/pdf.worker.min.mjs?worker'
import { pdfState, closePdf, isNativeApp } from '../composables/pdfViewer'

const MIN_SCALE = 0.5
const MAX_SCALE = 3

const loading = ref(false)
const error = ref('')
const pageCount = ref(0)
const scale = ref(1)
const scroller = ref(null)
const canvasRefs = ref([])
const downloading = ref(false)
// Toast singkat (sukses / gagal unduh) — TIDAK memakai `error` agar tampilan PDF
// tidak ikut hilang saat unduhan gagal.
const toast = ref('')
let toastTimer = null
function showToast(msg) {
	toast.value = msg
	clearTimeout(toastTimer)
	toastTimer = setTimeout(() => (toast.value = ''), 3500)
}

let pdfDoc = null
let renderToken = 0

function close() {
	closePdf()
}

// Nama file unduhan dari judul viewer (pastikan berakhiran .pdf).
function downloadName() {
	const t = (pdfState.title || 'dokumen').split(/[?#]/)[0]
	return /\.pdf$/i.test(t) ? t : `${t}.pdf`
}

// Blob → base64 murni (tanpa prefix data:) untuk Capacitor Filesystem.writeFile.
function blobToBase64(blob) {
	return new Promise((resolve, reject) => {
		const r = new FileReader()
		r.onerror = () => reject(new Error('Gagal membaca file.'))
		r.onloadend = () => resolve(String(r.result || '').split(',')[1] || '')
		r.readAsDataURL(blob)
	})
}

// --- Simpan di aplikasi native (APK Capacitor) --------------------------------
// Android WebView TIDAK punya download manager: `<a download>` & blob URL
// diabaikan. Jadi di native file ditulis lewat plugin `@capacitor/filesystem`.
//
// Urutan strategi (utamakan UNDUH LANGSUNG, tanpa share sheet):
//   1. Tulis ke folder publik Documents → file langsung muncul di File Manager.
//      Butuh izin storage di Android ≤10 → diminta lebih dulu.
//   2. Kalau ditolak (Android 11+ scoped storage sering memblokir folder publik),
//      baru fallback: tulis ke cache + share sheet `@capacitor/share`.
// Plugin diakses via bridge runtime (window.Capacitor.Plugins), jadi tak perlu
// import paket npm-nya di web — cukup terpasang di build native.
async function saveNative(blob) {
	const Plugins = (window.Capacitor && window.Capacitor.Plugins) || {}
	const Filesystem = Plugins.Filesystem
	if (!Filesystem || typeof Filesystem.writeFile !== 'function') {
		throw new Error('Plugin penyimpanan (@capacitor/filesystem) belum terpasang di aplikasi.')
	}
	const fileName = downloadName()
	const data = await blobToBase64(blob)

	// 1) Unduh langsung ke folder publik Documents.
	try {
		if (typeof Filesystem.checkPermissions === 'function') {
			const st = await Filesystem.checkPermissions()
			if (
				st &&
				st.publicStorage !== 'granted' &&
				typeof Filesystem.requestPermissions === 'function'
			) {
				await Filesystem.requestPermissions()
			}
		}
		await Filesystem.writeFile({
			path: fileName,
			data,
			directory: 'DOCUMENTS',
			recursive: true,
		})
		showToast(`Tersimpan di Documents/${fileName}`)
		return
	} catch (e) {
		// Tulis ke folder publik ditolak → lanjut ke cara berbagi di bawah.
	}

	// 2) Fallback: cache + share sheet (user pilih "Simpan ke File" / kirim).
	const written = await Filesystem.writeFile({
		path: fileName,
		data,
		directory: 'CACHE',
		recursive: true,
	})
	let uri = written && written.uri
	if (!uri && typeof Filesystem.getUri === 'function') {
		const g = await Filesystem.getUri({ path: fileName, directory: 'CACHE' })
		uri = g && g.uri
	}
	const Share = Plugins.Share
	if (Share && typeof Share.share === 'function' && uri) {
		// files[] → Share memakai FileProvider bawaan Capacitor (aman di Android 7+).
		await Share.share({
			title: fileName,
			url: uri,
			files: [uri],
			dialogTitle: 'Simpan atau bagikan PDF',
		})
		return
	}
	throw new Error('Tidak bisa menyimpan file ke penyimpanan perangkat.')
}

// --- Simpan di browser biasa (web) --------------------------------------------
function saveWeb(blob) {
	const objUrl = URL.createObjectURL(blob)
	const a = document.createElement('a')
	a.href = objUrl
	a.download = downloadName()
	document.body.appendChild(a)
	a.click()
	a.remove()
	setTimeout(() => URL.revokeObjectURL(objUrl), 1000)
}

// Unduh PDF: ambil sebagai blob (bawa cookie session untuk file private), lalu
// simpan sesuai lingkungan — native (Capacitor) vs web.
async function download() {
	if (!pdfState.url || downloading.value) return
	downloading.value = true
	try {
		const res = await fetch(pdfState.url, { credentials: 'include' })
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const blob = await res.blob()
		if (isNativeApp()) await saveNative(blob)
		else saveWeb(blob)
	} catch (e) {
		showToast(`Gagal mengunduh: ${e?.message || e}`)
	} finally {
		downloading.value = false
	}
}

async function load(url) {
	// Batalkan render sebelumnya (token) & bersihkan dokumen lama.
	renderToken++
	error.value = ''
	pageCount.value = 0
	canvasRefs.value = []
	scale.value = 1
	if (pdfDoc) {
		try {
			pdfDoc.destroy()
		} catch (e) {
			/* ignore */
		}
		pdfDoc = null
	}
	if (!url) return
	loading.value = true
	try {
		// Port worker dibuat BARU tiap muat: pdfDoc.destroy() di atas mematikan
		// worker sebelumnya, jadi port lama tak bisa dipakai ulang.
		pdfjsLib.GlobalWorkerOptions.workerPort = new PdfWorker()
		// withCredentials → kirim cookie session (file private same-origin).
		const task = pdfjsLib.getDocument({ url, withCredentials: true })
		pdfDoc = await task.promise
		pageCount.value = pdfDoc.numPages
		loading.value = false
		await nextTick()
		await renderAll()
	} catch (e) {
		loading.value = false
		error.value = 'Gagal memuat PDF.\n' + (e?.message || e)
	}
}

async function renderAll() {
	if (!pdfDoc) return
	const token = renderToken
	// Lebar kontainer (dikurangi padding) → skala fit-width dasar, dikali `scale`.
	const containerWidth = (scroller.value?.clientWidth || 360) - 24
	const dpr = window.devicePixelRatio || 1
	for (let i = 1; i <= pdfDoc.numPages; i++) {
		if (token !== renderToken) return // dibatalkan (URL berubah / ditutup)
		const page = await pdfDoc.getPage(i)
		const base = page.getViewport({ scale: 1 })
		const fit = containerWidth / base.width
		const viewport = page.getViewport({ scale: fit * scale.value })
		const canvas = canvasRefs.value[i - 1]
		if (!canvas) continue
		const ctx = canvas.getContext('2d')
		canvas.width = Math.floor(viewport.width * dpr)
		canvas.height = Math.floor(viewport.height * dpr)
		canvas.style.width = Math.floor(viewport.width) + 'px'
		canvas.style.height = Math.floor(viewport.height) + 'px'
		ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
		await page.render({ canvasContext: ctx, viewport }).promise
	}
}

async function zoom(delta) {
	const next = Math.min(MAX_SCALE, Math.max(MIN_SCALE, scale.value + delta))
	if (next === scale.value) return
	scale.value = next
	await nextTick()
	await renderAll()
}

// Muat ulang tiap kali URL berubah / viewer dibuka.
watch(
	() => (pdfState.open ? pdfState.url : ''),
	(url) => {
		if (url) load(url)
	},
	{ immediate: true }
)
</script>
