<template>
	<div class="min-h-dvh flex items-start justify-center bg-[#f4f4f4] px-6 pt-24 sm:pt-32">
		<div class="w-full max-w-sm flex flex-col items-center">
			<h1 class="text-3xl font-bold text-primary mb-1">Juragan</h1>
			<p class="text-[#1a1a1a] text-sm mb-8 font-medium tracking-wide">
				masukkan email dan kata sandi
			</p>

			<form @submit.prevent="handleLogin" class="w-full flex flex-col space-y-4">
				<input
					v-model="email"
					type="text"
					inputmode="email"
					autocomplete="username"
					placeholder="Email atau Username"
					required
					class="w-full px-5 py-3.5 bg-transparent border border-[#2c3e50] rounded-[1.25rem] text-[#1a1a1a] placeholder-gray-600 focus:outline-none focus:ring-1 focus:ring-[#2c3e50] transition-shadow"
				/>

				<div class="relative">
					<input
						v-model="password"
						:type="showPassword ? 'text' : 'password'"
						placeholder="Kata sandi"
						required
						class="w-full pl-5 pr-12 py-3.5 bg-transparent border border-[#2c3e50] rounded-[1.25rem] text-[#1a1a1a] placeholder-gray-600 focus:outline-none focus:ring-1 focus:ring-[#2c3e50] transition-shadow"
					/>
					<button
						type="button"
						@click="showPassword = !showPassword"
						:aria-label="
							showPassword ? 'Sembunyikan kata sandi' : 'Tampilkan kata sandi'
						"
						class="absolute inset-y-0 right-0 flex items-center pr-4 text-[#2c3e50] hover:text-[#1a1a1a] focus:outline-none"
					>
						<svg
							v-if="showPassword"
							xmlns="http://www.w3.org/2000/svg"
							width="20"
							height="20"
							viewBox="0 0 24 24"
							fill="none"
							stroke="currentColor"
							stroke-width="1.75"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M9.88 9.88a3 3 0 1 0 4.24 4.24" />
							<path
								d="M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68"
							/>
							<path
								d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61"
							/>
							<line x1="2" y1="2" x2="22" y2="22" />
						</svg>
						<svg
							v-else
							xmlns="http://www.w3.org/2000/svg"
							width="20"
							height="20"
							viewBox="0 0 24 24"
							fill="none"
							stroke="currentColor"
							stroke-width="1.75"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
							<circle cx="12" cy="12" r="3" />
						</svg>
					</button>
				</div>

				<button
					type="submit"
					:disabled="session.login.loading"
					class="w-full mt-2 py-4 bg-primary text-white rounded-[1.25rem] font-semibold text-base hover:bg-primary-hover focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-colors disabled:opacity-70 flex justify-center items-center"
				>
					<span v-if="session.login.loading">Memproses...</span>
					<span v-else>Masuk</span>
				</button>

				<div
					v-if="session.errorMessage"
					role="alert"
					class="mt-2 px-4 py-3 bg-red-50 border border-red-200 rounded-[0.875rem] text-red-700 text-sm text-center"
				>
					{{ session.errorMessage }}
				</div>
			</form>
		</div>
	</div>
</template>

<script setup>
import { ref } from 'vue'
import { session } from '../data/session'

const email = ref('')
const password = ref('')
const showPassword = ref(false)

const handleLogin = async () => {
	session.errorMessage = ''
	try {
		await session.login.submit({
			email: email.value.trim(),
			password: password.value,
		})
	} catch (error) {
		console.error('Login gagal:', error)
	}
}
</script>
